public class Solution {
    public static void main(String[] args) {
        double a = 1, b = -5, c = 6;
        System.out.println("Coefficients: a=" + a + ", b=" + b + ", c=" + c);
        if (a == 0) {
            System.out.println("Equation is linear, not quadratic.");
        } else {
            double d = b * b - 4 * a * c;
            if (d > 0) {
                double r1 = (-b + Math.sqrt(d)) / (2 * a);
                double r2 = (-b - Math.sqrt(d)) / (2 * a);
                System.out.printf("Two distinct real roots: %.1f and %.1f%n", r1, r2);
            } else if (d == 0) {
                double r = -b / (2 * a);
                System.out.printf("One repeated real root: %.1f%n", r);
            } else {
                System.out.println("Complex conjugate roots exist.");
            }
        }
    }
}

