public class Solution {
    public static String validateDate(int y, int m, int d) {
        if (y < 1) return "Invalid year";
        if (m < 1 || m > 12) return "Invalid month";
        boolean isLeap = (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
        int maxDay;
        if (m == 2) maxDay = isLeap ? 29 : 28;
        else if (m == 4 || m == 6 || m == 9 || m == 11) maxDay = 30;
        else maxDay = 31;

        if (d < 1 || d > maxDay) {
            return "Invalid day for specified month (max: " + maxDay + ")";
        }
        return "Valid Date";
    }

    public static void main(String[] args) {
        int y = 2023, m = 2, d = 29;
        System.out.printf("Testing %04d-%02d-%02d: %s%n", y, m, d, validateDate(y, m, d));
    }
}

