public class Solution {
    public static boolean isInside(double[] polyX, double[] polyY, double px, double py) {
        int n = polyX.length;
        boolean inside = false;
        for (int i = 0, j = n - 1; i < n; j = i++) {
            if ((polyY[i] > py) != (polyY[j] > py) &&
                (px < (polyX[j] - polyX[i]) * (py - polyY[i]) / (polyY[j] - polyY[i]) + polyX[i])) {
                inside = !inside;
            }
        }
        return inside;
    }

    public static void main(String[] args) {
        double[] px = {0, 10, 10, 0};
        double[] py = {0, 0, 10, 10};
        double tx = 5, ty = 5;
        System.out.println("Testing Point (" + tx + ", " + ty + ") in square:");
        System.out.println("Result: " + (isInside(px, py, tx, ty) ? "Inside" : "Outside"));
    }
}

