public class Solution {
    public static boolean overlap(int s1, int e1, int s2, int e2) {
        return s1 < e2 && s2 < e1;
    }

    public static void main(String[] args) {
        int s1 = 9, e1 = 11;
        int s2 = 10, e2 = 12;
        int s3 = 10, e3 = 13;

        boolean o12 = overlap(s1, e1, s2, e2);
        boolean o23 = overlap(s2, e2, s3, e3);
        boolean o13 = overlap(s1, e1, s3, e3);

        int maxStart = Math.max(s1, Math.max(s2, s3));
        int minEnd = Math.min(e1, Math.min(e2, e3));
        boolean triple = maxStart < minEnd;

        if (triple) {
            System.out.println("Schedule Conflict: Triple Overlap");
        } else if (o12 || o23 || o13) {
            System.out.println("Schedule Conflict: Pairwise Overlaps");
        } else {
            System.out.println("Schedule Conflict: All Distinct");
        }
    }
}

public class Solution {
    public static boolean isValidTransition(String from, String to) {
        if ("CREATED".equals(from)) {
            return "PAID".equals(to) || "CANCELLED".equals(to);
        } else if ("PAID".equals(from)) {
            return "SHIPPED".equals(to) || "CANCELLED".equals(to);
        } else if ("SHIPPED".equals(from)) {
            return "DELIVERED".equals(to);
        } else if ("DELIVERED".equals(from) || "CANCELLED".equals(from)) {
            return false; // Terminal states
        }
        return false;
    }

    public static void main(String[] args) {
        String current = "PAID";
        String nextValid = "SHIPPED";
        String nextInvalid = "DELIVERED";

        System.out.println(current + " -> " + nextValid + ": " + isValidTransition(current, nextValid));
        System.out.println(current + " -> " + nextInvalid + ": " + isValidTransition(current, nextInvalid));
    }
}
